// GENERATED by scripts/build-courses.ts from src/lib/courses/content — edit those files, then run: npm run courses
import type { LessonText } from '../types';
const text: LessonText[][] = [[{"say":"Statistics starts with describing data clearly. On the AP exam, always describe shape, center, spread and unusual features, in context.","blocks":[{"t":"p","text":"Categorical variables place individuals into groups (eye color); quantitative variables are numerical measurements (height). Display categorical data with bar charts; quantitative data with dotplots, histograms, stemplots and boxplots."},{"t":"key","text":"Describe a distribution with SOCS: Shape, Outliers, Center, Spread, always in context."},{"t":"list","items":["Shape: symmetric, skewed left (tail to the left), skewed right (tail to the right), unimodal or bimodal.","Center: mean (x̄) or median.","Spread: standard deviation, range or IQR.","Outliers: below Q1 − 1.5·IQR or above Q3 + 1.5·IQR."]},{"t":"p","text":"In a right-skewed distribution, the mean is usually greater than the median. Use median and IQR for skewed data (they're resistant); use mean and standard deviation for roughly symmetric data."},{"t":"ex","problem":"Q1 = 20 and Q3 = 30. Is 48 an outlier?","steps":["IQR = 10; upper fence = 30 + 1.5(10) = 45"],"answer":"Yes, 48 > 45, so it's an outlier"}]},{"say":"The normal distribution is the most important curve in statistics. z-scores let you compare values from different distributions.","blocks":[{"t":"key","text":"z = (x − μ)/σ measures how many standard deviations a value is from the mean."},{"t":"p","text":"The empirical rule for normal distributions: about 68% of values are within 1σ, 95% within 2σ, and 99.7% within 3σ of the mean."},{"t":"p","text":"For other proportions, use a z-table or calculator (normalcdf / invNorm)."},{"t":"ex","problem":"SAT Math scores are N(520, 110). What percent score above 740?","steps":["z = (740 − 520)/110 = 2","About 2.5% lie above z = 2 (half of the 5% outside ±2σ)"],"answer":"about 2.5%"},{"t":"p","text":"A percentile tells the percent of values at or below a given value. Transforming data: adding a constant shifts the center but not the spread; multiplying by a constant multiplies both center and spread."}]}],[{"say":"When we measure two quantitative variables, a scatterplot shows the relationship. Correlation measures its strength.","blocks":[{"t":"p","text":"Describe a scatterplot with DOFS: Direction (positive or negative), Outliers, Form (linear or curved), Strength, in context."},{"t":"key","text":"The correlation r ranges from −1 to 1. It measures the strength and direction of a linear relationship only."},{"t":"list","items":["r near ±1: strong linear relationship. r near 0: weak or no linear relationship.","r has no units and doesn't change if you switch x and y or change units.","r is not resistant: one outlier can change it a lot."]},{"t":"oops","text":"Correlation does not imply causation. Ice cream sales and drownings are correlated because both increase in summer (a lurking variable)."},{"t":"p","text":"Two-way tables summarize two categorical variables. Use joint, marginal and conditional relative frequencies to check for association."}]},{"say":"The regression line is the best-fitting line through a scatterplot. Interpreting its slope in context is a guaranteed AP question.","blocks":[{"t":"key","text":"ŷ = a + bx. Slope b = r(s_y/s_x); the line always passes through (x̄, ȳ)."},{"t":"p","text":"Interpret the slope: \"For each additional [x unit], the predicted [y] increases/decreases by [b].\""},{"t":"p","text":"A residual = actual − predicted = y − ŷ. A residual plot with no pattern means a linear model is appropriate; a curved pattern means it isn't."},{"t":"p","text":"r² is the coefficient of determination: the percent of variation in y explained by the linear model with x."},{"t":"ex","problem":"ŷ = 30 + 4.5x, where x is hours studied and y is test score. A student studied 8 hours and scored 70. Find the residual.","steps":["Predicted: 30 + 4.5(8) = 66","Residual: 70 − 66"],"answer":"4 (the student scored 4 points above the prediction)"},{"t":"oops","text":"Extrapolation (predicting far outside the range of the data) is unreliable."}]}],[{"say":"How data is collected matters more than any calculation. A biased sample gives a wrong answer, no matter how big it is.","blocks":[{"t":"p","text":"A population is the entire group of interest; a sample is the part we actually study. A census collects data from everyone."},{"t":"key","text":"Random sampling methods: simple random sample (SRS), stratified (random samples within similar groups), cluster (randomly select whole groups) and systematic (every kth individual after a random start)."},{"t":"p","text":"Sources of bias:"},{"t":"list","items":["Convenience sampling: choosing easy-to-reach people.","Voluntary response: people choose to respond, usually those with strong opinions.","Undercoverage: some groups are left out.","Nonresponse: selected people don't respond.","Response bias: question wording or interviewer effects lead to inaccurate answers."]}]},{"say":"Only well-designed experiments can show cause and effect. Here's what makes an experiment trustworthy.","blocks":[{"t":"p","text":"In an observational study, researchers observe without imposing treatments. In an experiment, they deliberately assign treatments."},{"t":"key","text":"Principles of experimental design: comparison (at least two groups), random assignment of treatments, control of other variables, and replication (enough experimental units)."},{"t":"list","items":["A control group gets no treatment or a placebo.","Blinding: subjects (single-blind) or both subjects and evaluators (double-blind) don't know who gets which treatment.","Blocking: grouping similar units and randomizing within blocks reduces variability. A matched-pairs design is a special case."]},{"t":"p","text":"Scope of inference: random sampling allows generalizing to the population; random assignment allows cause-and-effect conclusions."}]}],[{"say":"Probability is the language of uncertainty. These rules are used in every later unit.","blocks":[{"t":"key","text":"P(A or B) = P(A) + P(B) − P(A and B). P(A and B) = P(A) · P(B | A). Events are independent if P(B | A) = P(B)."},{"t":"list","items":["Mutually exclusive events can't happen together: P(A and B) = 0.","Complement: P(not A) = 1 − P(A). \"At least one\" problems are often easiest with the complement.","Conditional probability: P(A | B) = P(A and B)/P(B)."]},{"t":"ex","problem":"The probability a part is defective is 0.05. What's the probability that at least one of 3 independent parts is defective?","steps":["P(none defective) = 0.95³ ≈ 0.857","P(at least one) = 1 − 0.857"],"answer":"about 0.143"},{"t":"p","text":"Simulation uses random numbers to model chance processes and estimate probabilities."}]},{"say":"Random variables turn chance outcomes into numbers. Two special distributions show up constantly on the exam.","blocks":[{"t":"p","text":"The expected value of a discrete random variable is μ = Σ x·P(x), the long-run average. Its standard deviation measures typical variation from the mean."},{"t":"p","text":"Combining random variables: means add (μ_X+Y = μ_X + μ_Y). For independent variables, variances add (even when subtracting): σ²_X±Y = σ²_X + σ²_Y."},{"t":"key","text":"Binomial setting (BINS): Binary outcomes, Independent trials, fixed Number of trials n, Same probability p. P(X = k) = C(n,k)pᵏ(1 − p)ⁿ⁻ᵏ, with μ = np and σ = √(np(1 − p))."},{"t":"p","text":"Geometric setting: count trials until the first success. P(X = k) = (1 − p)ᵏ⁻¹p, with mean 1/p."},{"t":"ex","problem":"A basketball player makes 70% of free throws. In 10 shots, what's the expected number made and the standard deviation?","steps":["μ = np = 10(0.7) = 7","σ = √(10 × 0.7 × 0.3) = √2.1"],"answer":"μ = 7, σ ≈ 1.45"}]}],[{"say":"Different samples give different results. A sampling distribution describes how a statistic varies from sample to sample.","blocks":[{"t":"p","text":"A parameter describes a population (p, μ); a statistic describes a sample (p̂, x̄). The sampling distribution of a statistic is the distribution of its values from all possible samples of the same size."},{"t":"key","text":"A statistic is unbiased if its sampling distribution is centered at the parameter. Larger samples reduce variability (spread decreases by a factor of √n)."},{"t":"p","text":"Sampling distribution of p̂: mean p, standard deviation √(p(1 − p)/n). It's approximately normal if np ≥ 10 and n(1 − p) ≥ 10."},{"t":"ex","problem":"In a population, p = 0.6. For samples of n = 100, find the mean and standard deviation of p̂.","steps":["Mean = 0.6","SD = √(0.6 × 0.4/100) = √0.0024"],"answer":"mean 0.6, SD ≈ 0.049"}]},{"say":"The Central Limit Theorem is statistical magic: sample means become normal even when the population isn't.","blocks":[{"t":"p","text":"Sampling distribution of x̄: mean μ, standard deviation σ/√n."},{"t":"key","text":"Central Limit Theorem: for large enough samples (n ≥ 30 is a common guideline), the sampling distribution of x̄ is approximately normal, regardless of the population's shape."},{"t":"p","text":"If the population itself is normal, x̄ is normal for any sample size."},{"t":"ex","problem":"Commute times have μ = 30 minutes and σ = 12, with a right-skewed shape. For random samples of 36 commuters, describe the sampling distribution of x̄.","steps":["n = 36 ≥ 30, so the CLT applies: approximately normal","Mean 30, SD = 12/√36 = 2"],"answer":"approximately N(30, 2)"},{"t":"p","text":"The 10% condition: when sampling without replacement, the sample should be less than 10% of the population for the standard deviation formulas to work."}]}],[{"say":"A confidence interval gives a range of plausible values for a parameter. Interpreting it correctly earns big points.","blocks":[{"t":"key","text":"Confidence interval = statistic ± (critical value)(standard error). For a proportion: p̂ ± z*√(p̂(1 − p̂)/n)."},{"t":"p","text":"Conditions: Random sample; 10% condition; Large counts (np̂ ≥ 10 and n(1 − p̂) ≥ 10)."},{"t":"p","text":"Common critical values: 90% → 1.645, 95% → 1.96, 99% → 2.576."},{"t":"ex","problem":"In a random sample of 400 students, 240 support a later start. Construct a 95% confidence interval.","steps":["p̂ = 0.6; SE = √(0.6 × 0.4/400) ≈ 0.0245","0.6 ± 1.96(0.0245) = 0.6 ± 0.048"],"answer":"(0.552, 0.648)"},{"t":"p","text":"Interpretation: \"We are 95% confident that the interval from 0.552 to 0.648 captures the true proportion of all students who support a later start.\""},{"t":"p","text":"Higher confidence → wider interval. Larger sample → narrower interval."}]},{"say":"A significance test asks whether data gives convincing evidence against a claim. Here's the four-step process.","blocks":[{"t":"key","text":"State hypotheses (H₀: p = p₀; Hₐ: p >, <, or ≠ p₀), check conditions, calculate the test statistic and P-value, then conclude in context."},{"t":"p","text":"Test statistic: z = (p̂ − p₀)/√(p₀(1 − p₀)/n). The P-value is the probability of getting a result at least this extreme if H₀ is true."},{"t":"p","text":"If P-value < α (often 0.05), reject H₀: there is convincing evidence for Hₐ. Otherwise, fail to reject H₀ (never \"accept\" it)."},{"t":"list","items":["Type I error: rejecting H₀ when it's true (probability α).","Type II error: failing to reject H₀ when Hₐ is true.","Power = 1 − P(Type II error): the probability of correctly rejecting a false H₀. Power increases with larger samples, larger α, and larger true effects."]}]}],[{"say":"When we don't know σ, which is almost always, we use the t-distribution instead of z.","blocks":[{"t":"key","text":"For means, use t* with df = n − 1: x̄ ± t*(s/√n). Test statistic: t = (x̄ − μ₀)/(s/√n)."},{"t":"p","text":"t-distributions are bell-shaped but have fatter tails than the normal distribution; they approach the normal as df increases."},{"t":"p","text":"Conditions: random sample; 10% condition; normal/large sample (n ≥ 30, or the population is approximately normal, or the sample data show no strong skew or outliers)."},{"t":"ex","problem":"A random sample of 16 batteries has x̄ = 49 hours and s = 4. Is there evidence the mean lifetime is less than the claimed 50 hours?","steps":["t = (49 − 50)/(4/√16) = −1","With df = 15, the P-value ≈ 0.17"],"answer":"P-value > 0.05, so we fail to reject H₀; not convincing evidence the mean is below 50 hours"}]},{"say":"Many studies compare two groups. The key is recognizing whether the data are independent or paired.","blocks":[{"t":"key","text":"Paired data: the same individuals measured twice, or matched pairs. Analyze the differences with one-sample t-procedures on d."},{"t":"p","text":"Two independent samples: use two-sample t-procedures: (x̄₁ − x̄₂) ± t*√(s₁²/n₁ + s₂²/n₂)."},{"t":"p","text":"For two proportions: (p̂₁ − p̂₂) ± z*√(p̂₁(1 − p̂₁)/n₁ + p̂₂(1 − p̂₂)/n₂). Tests of H₀: p₁ = p₂ use a pooled proportion."},{"t":"ex","problem":"Students take a test before and after tutoring. Which procedure?","steps":["The same students are measured twice"],"answer":"Paired t-procedure on the differences"},{"t":"p","text":"If a confidence interval for a difference contains 0, there's no convincing evidence of a difference."}]}],[{"say":"Chi-square tests handle categorical data with more than two categories. Three versions cover different questions.","blocks":[{"t":"key","text":"χ² = Σ (observed − expected)²/expected. Larger χ² means the data differ more from what H₀ predicts."},{"t":"list","items":["Goodness of fit: does one categorical variable match a claimed distribution? df = categories − 1.","Homogeneity: do several populations have the same distribution of a categorical variable? (Separate samples.)","Independence: are two categorical variables associated in one population? (One sample, two variables.)"]},{"t":"p","text":"For two-way tables, expected count = (row total × column total)/grand total, and df = (rows − 1)(columns − 1)."},{"t":"p","text":"Condition: all expected counts are at least 5."},{"t":"ex","problem":"A die is rolled 60 times. What is the expected count for each face under H₀ that the die is fair?","steps":["60 rolls ÷ 6 faces"],"answer":"10 per face"}]},{"say":"Half the battle on AP free response is picking the right procedure. Here's a quick decision guide.","blocks":[{"t":"key","text":"Ask: Is the data categorical or quantitative? One sample, two samples, or paired? Estimating (interval) or testing a claim?"},{"t":"list","items":["One categorical proportion: one-proportion z.","Two proportions: two-proportion z.","More than two categories or a two-way table: chi-square.","One mean or paired differences: one-sample t.","Two independent means: two-sample t.","Relationship between two quantitative variables: t for the slope."]},{"t":"ex","problem":"A researcher wants to estimate the average daily screen time of teens. Which procedure?","steps":["Quantitative (minutes), one sample, estimating"],"answer":"One-sample t-interval for a mean"},{"t":"tip","text":"Always state the procedure by name, check conditions, show the calculation, and write a conclusion in context. Each part earns points."}]}],[{"say":"Is a relationship in sample data real, or could it be chance? Inference for slope answers that.","blocks":[{"t":"p","text":"The population regression line is μ_y = α + βx. The sample slope b estimates the true slope β."},{"t":"key","text":"Confidence interval for slope: b ± t*(SE_b), with df = n − 2. Test H₀: β = 0 (no linear relationship) with t = b/SE_b."},{"t":"p","text":"Conditions (LINER): Linear relationship, Independent observations, Normal residuals, Equal variance of residuals (no fanning in the residual plot), Random sample."},{"t":"p","text":"Computer output gives b, SE_b, t and the P-value. Know how to read it: the slope is in the row for the explanatory variable."},{"t":"ex","problem":"Output shows slope b = 2.4, SE_b = 0.8, n = 22. Find the test statistic for H₀: β = 0.","steps":["t = 2.4/0.8"],"answer":"t = 3.0, with df = 20"},{"t":"p","text":"A small P-value means convincing evidence of a linear relationship between x and y in the population."}]},{"say":"The AP Statistics exam rewards clear communication as much as correct math. Let's practice writing like a statistician.","blocks":[{"t":"key","text":"Every conclusion must be in context, use the language of probability correctly, and not overstate the evidence."},{"t":"p","text":"Strong writing habits:"},{"t":"list","items":["Name the parameter: \"p = the true proportion of all US teens who…\"","State hypotheses in symbols and words.","Check every condition and say why it's met.","Link the P-value to α: \"Because the P-value of 0.012 < α = 0.05, we reject H₀.\"","Conclude in context: \"There is convincing evidence that…\"","Never say \"accept H₀\" or \"prove.\""]},{"t":"ex","problem":"Improve: \"The P-value is 0.30, so H₀ is true.\"","steps":["We can't prove H₀; we only fail to reject it"],"answer":"\"Because the P-value of 0.30 > 0.05, we fail to reject H₀. We do not have convincing evidence that [Hₐ in context].\""}]}]];
export default text;
